        if (!key.length()) continue;           // not an action line
        String value = atechJsonString(line, "value", end);
        _atech_error = nullptr;
        if (atechDispatch(key, value)) {
            atechAck(key, _atech_error == nullptr, _atech_error);
            _atech_error = nullptr;
        } else {
            atech_action = key;                 // offered to code.loop for this pass
            atech_value = value;
        }
        return;                                 // one action per loop pass
